import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CRFziyHp.js";const b=JSON.parse('{"title":"网站信息","description":"网站信息：灵萌 后台配置官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"config/site-info.md","filePath":"config/site-info.md","lastUpdated":1785018026000}'),o={name:"config/site-info.md"};function i(h,t,n,l,s,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="网站信息" tabindex="-1">网站信息 <a class="header-anchor" href="#网站信息" aria-label="Permalink to &quot;网站信息&quot;">​</a></h1><p>路径：<strong>系统设置 → 网站信息</strong></p><p>管理 <strong>对用户公开展示</strong> 的站点名称、Logo、备案与客服信息。与 <strong>系统配置</strong> 不同：此处不涉及密钥和支付，运营人员也可维护。</p><hr><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>作用</th><th>填写建议</th><th>展示位置</th></tr></thead><tbody><tr><td>网站名称</td><td>站点全称</td><td>如「灵萌校园」「XX 大学圈」</td><td>浏览器标题、分享卡片、部分页脚</td></tr><tr><td>网站简称</td><td>短名称</td><td>2～6 字，如「灵萌」</td><td>空间不足时的缩写展示</td></tr><tr><td>网站描述</td><td>站点简介</td><td>1～2 句话，含核心功能</td><td>SEO、分享摘要</td></tr><tr><td>关键词</td><td>SEO 关键词</td><td>逗号分隔，如 <code>校园,社交,二手</code></td><td>搜索引擎</td></tr><tr><td>版本号</td><td>设置页展示用</td><td>如 <code>v1.0.0</code>，可与发版节奏同步</td><td>客户端「关于」/ 设置页</td></tr></tbody></table><p><strong>操作步骤：</strong></p><ol><li>进入 <strong>系统设置 → 网站信息</strong></li><li>填写名称与描述（上线前 <strong>必做</strong>）</li><li>点击 <strong>保存</strong></li><li>客户端杀进程重进，或下拉刷新，查看标题与关于页</li></ol><hr><h2 id="logo-与图标" tabindex="-1">Logo 与图标 <a class="header-anchor" href="#logo-与图标" aria-label="Permalink to &quot;Logo 与图标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>规格建议</th><th>说明</th></tr></thead><tbody><tr><td>网站 Logo</td><td>PNG 透明底，建议 512×512 以内</td><td>点 <strong>选择文件</strong> 从媒体库上传；用于管理后台和部分 C 端位置</td></tr><tr><td>网站 Favicon</td><td>正方形，32×32 或 64×64</td><td>浏览器标签小图标；保存后 <strong>H5 刷新</strong> 才更新</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">先配置文件存储</p><p>上传 Logo 前须已在 <strong>系统配置 → 文件存储</strong> 配好本地或云存储，否则选图失败。</p></div><hr><h2 id="版权与备案" tabindex="-1">版权与备案 <a class="header-anchor" href="#版权与备案" aria-label="Permalink to &quot;版权与备案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>版权信息</td><td><code>© 2026 XX 科技有限公司</code></td><td>页脚展示</td></tr><tr><td>ICP 备案号</td><td><code>京ICP备XXXXXXXX号</code></td><td>国内站点 <strong>强烈建议</strong> 填写，<a href="https://beian.miit.gov.cn" target="_blank" rel="noreferrer">工信部备案</a></td></tr><tr><td>公安备案号</td><td><code>京公网安备XXXXXXXXXXXX号</code></td><td>可选</td></tr><tr><td>公安备案链接</td><td><code>http://www.beian.gov.cn/portal/registerSystemInfo?recordcode=...</code></td><td>与公安备案号成对出现</td></tr></tbody></table><hr><h2 id="客服信息" tabindex="-1">客服信息 <a class="header-anchor" href="#客服信息" aria-label="Permalink to &quot;客服信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>作用</th></tr></thead><tbody><tr><td>客服电话</td><td>通知模板等可使用变量展示</td></tr><tr><td>客服微信</td><td>用户联系客服</td></tr><tr><td>工作时间</td><td>如 <code>工作日 9:00-18:00</code></td></tr></tbody></table><hr><h2 id="只读信息" tabindex="-1">只读信息 <a class="header-anchor" href="#只读信息" aria-label="Permalink to &quot;只读信息&quot;">​</a></h2><p>页面底部通常展示：<strong>配置 ID</strong>、<strong>创建时间</strong>、<strong>更新时间</strong>，用于与技术支持核对配置版本。</p><hr><h2 id="与-ui-编辑器的关系" tabindex="-1">与 UI 编辑器的关系 <a class="header-anchor" href="#与-ui-编辑器的关系" aria-label="Permalink to &quot;与 UI 编辑器的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>网站信息</th><th>UI 编辑器</th></tr></thead><tbody><tr><td>站点名称</td><td>✅ 全站默认</td><td>各页面导航标题可单独覆盖</td></tr><tr><td>Logo</td><td>✅ 全站</td><td>TabBar、首页头图等在 <strong>UI管理</strong> 单独配</td></tr><tr><td>首页布局</td><td>❌</td><td><strong>UI管理 → 页面配置 → 应用首页</strong></td></tr></tbody></table><p>改首页视觉请用 <a href="/features/ui-editor/">UI 可视化编辑器</a>，不要只在网站信息里改名称。</p><hr><h2 id="验证-checklist" tabindex="-1">验证 checklist <a class="header-anchor" href="#验证-checklist" aria-label="Permalink to &quot;验证 checklist&quot;">​</a></h2><ul><li>[ ] 网站名称、Logo 已保存</li><li>[ ] H5 打开站点，标签页标题正确</li><li>[ ] 页脚备案号可点击（若配置了公安链接）</li><li>[ ] 分享小程序卡片标题与描述合理（还可在 UI 页面配置里设 <strong>分享标题/分享图</strong>）</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/config/system-settings">系统配置总览</a></li><li><a href="/features/ui-editor/getting-started">UI 编辑器 — 快速上手</a></li></ul>',30)])])}const u=d(o,[["render",i]]);export{b as __pageData,u as default};
